    /**
     * Tests getting all KYCProfiles.
     *
     * @return    Collection
     */
    public List<KYCProfile> testGetAll() throws Throwable {
    LOGGER.info( "KYCProfileTest:testGetAll() - Retrieving Collection of KYCProfiles:" );

    StringBuilder msg = new StringBuilder( "-- Failed to get all KYCProfile : " );
    List<KYCProfile> collection  = null;

    try {
        // call the static get method on the KYCProfileService
        collection = service.getAllKYCProfile();

        if ( collection == null || collection.size() == 0 ) {
            LOGGER.warning( unexpectedErrorMsg );
            LOGGER.warning( "-- " + msg.toString() + " Empty collection returned."  );
        }
        else {
            // Now print out the values
            KYCProfile currEntity  = null;
            Iterator<KYCProfile> iter = collection.iterator();

            while( iter.hasNext() ) {
                // Retrieve the entity
                currEntity = iter.next();

                assertNotNull( currEntity,"-- null value object in Collection." );
                assertNotNull( currEntity.getKYCProfileId(), "-- value object in Collection has a null primary key" );

                LOGGER.info( " - " + currEntity.toString() );
            }
        }
    }
    catch ( Throwable e ){
        LOGGER.warning( unexpectedErrorMsg );
        LOGGER.warning( msg.toString() );

        throw e;
    }

    return( collection );
}

